-- title:  serpentine
-- author: Dave Templin
-- desc: Faithful recreation of Serpentine, a maze game like Pac-Man but with snakes! Originally written by David Snider and published by Broderbund for the Apple II in 1982.
-- site: https://github.com/dtempx/tic80
-- license: MIT
-- version: 1.01
-- script: lua
-- saveid: serpentine

-- debug
PLAYER_LIVES=3 -- LIVES $D8 = 3 at cold start (COLDSTART $0803), pen fill $8830-$884F
A2BOOT=true -- play the Apple II power-on intro before the title (false = straight to the title)

require "constants"
require "a2boot"
require "records"
