require "game_state"

-- power-on: reset the frame count and input latches, load the saved records
-- and theme, open on the title (COLDSTART $0803) behind the Apple II boot
-- intro (a2boot.lua; Apple II themes only)
function BOOT()
 frame=0 -- TIC() counter
 start_pressed=false -- A pressed since the last logic tick
 back_pressed=false -- B pressed since the last logic tick
 fire_pressed=false -- A or B pressed since the last logic tick
 menu_pressed=nil -- d-pad direction pressed since the last logic tick
 records_load() -- also the theme (theme_set)
 title_init()
 a2_display = apple2.boot{
  enabled = A2BOOT and theme_a2(), mode = theme_a2() and theme or 0,
  skip = true, fg = COLOR_SLOT_12, bg = BLACK,
  glyph = WHITE, transparent = BLACK,
  at_spr = SPRITE_BOOT_AT, title_spr = SPRITE_BOOT_TITLE,
  drive_base = BOOT_DRIVE_BASE, drive_midpoint = BOOT_DRIVE_MIDPOINT,
  mono = {
   background = BLACK, solid = {WHITE, DIM_WHITE, COLOR_SLOT_11, COLOR_SLOT_12},
   odd = {GREEN, ORANGE}, text = WHITE, overlay_dark = WHITE,
  },
 }
 if theme_a2() and theme ~= mono.mode then theme_set(mono.mode, false) end
end

-- one engine frame: the intro while it runs, else the game (dispatched by
-- game_state.lua, MAINLOOP $08FD), then the Apple II monitor post-process.
-- TIC-80 before 1.0 (e.g. the Miyoo Mini's RetroArch core) never calls
-- BOOT(), so the first TIC() runs it
function TIC()
 if not frame then BOOT() end
 if theme_a2() and apple2.tic() then return end
 tic_frame()
 if theme_a2() then mono.apply() end
end

